/* ---------- carousel ---------- */
const slides=[...document.querySelectorAll('.slide')],dots=document.getElementById('dots');
let cur=0,timer;
if(slides.length&&dots){
  slides.forEach((_,i)=>{const b=document.createElement('button');b.onclick=()=>show(i);dots.appendChild(b)});
  function show(i){
    cur=(i+slides.length)%slides.length;
    slides.forEach((s,n)=>s.classList.toggle('on',n===cur));
    [...dots.children].forEach((d,n)=>d.classList.toggle('on',n===cur));
    clearInterval(timer);timer=setInterval(()=>go(1),7000);
  }
  window.go=d=>show(cur+d);
  show(0);
}

